-- Batch pink-panther (Pink-Panther-A3-32-Mockups.zip): 1 new Laundries, 16 new tees.
-- Generated by scripts/batch/generate_batch_sql.mjs from batches/pink-panther.json.

insert into public.collections (id, name, short_name, tagline, description, featured_product_id, tint, accent, theme, show_on_home, sort_order)
select v.id, v.name, v.short_name, v.tagline, v.description, v.featured, v.tint, v.accent, v.theme, v.show_on_home, base.m + v.ord * 10
from (values
  ('pink-panther', 'Pink Panther Laundry', 'Pink Panther', 'Think pink.', 'The Pink Panther behind the camera, by the pool, and on the moon. Sixteen graphic tees in black and white.', 'pink-panther-instant-photographer', '#f7e1e8', '#a43964', 'pink-panther', true, 1)
) as v (id, name, short_name, tagline, description, featured, tint, accent, theme, show_on_home, ord)
cross join (select coalesce(max(sort_order), 0) as m from public.collections) as base;

insert into public.products (id, collection_id, name, description, default_color, sort_order)
select v.id, v.collection_id, v.name, v.description, v.default_color, base.m + v.ord * 10
from (values
  ('pink-panther-instant-photographer', 'pink-panther', 'Instant Photographer', 'Instant Photographer, a Pink Panther design on an oversized tee.', 'black', 1),
  ('pink-panther-no-spill-skater', 'pink-panther', 'No Spill Skater', 'No Spill Skater, a Pink Panther design on an oversized tee.', 'black', 2),
