  ('pink-panther-low-budget-wind-machine', 'pink-panther', 'Low Budget Wind Machine', 'Low Budget Wind Machine, a Pink Panther design on an oversized tee.', 'black', 4),
  ('pink-panther-record-store', 'pink-panther', 'Record Store', 'Record Store, a Pink Panther design on an oversized tee.', 'black', 5),
  ('pink-panther-bookworm', 'pink-panther', 'Bookworm', 'Bookworm, a Pink Panther design on an oversized tee.', 'black', 6),
  ('pink-panther-pizza-tail', 'pink-panther', 'Pizza Tail', 'Pizza Tail, a Pink Panther design on an oversized tee.', 'black', 7),
  ('pink-panther-sandcastle-architect', 'pink-panther', 'Sandcastle Architect', 'Sandcastle Architect, a Pink Panther design on an oversized tee.', 'black', 8),
  ('pink-panther-mirrorball', 'pink-panther', 'Mirrorball', 'Mirrorball, a Pink Panther design on an oversized tee.', 'black', 9),
  ('pink-panther-poolside', 'pink-panther', 'Poolside', 'Poolside, a Pink Panther design on an oversized tee.', 'black', 10),
  ('pink-panther-king-of-the-world', 'pink-panther', 'King Of The World', 'King Of The World, a Pink Panther design on an oversized tee.', 'black', 11),
  ('pink-panther-show-me-the-money', 'pink-panther', 'Show Me the Money', 'Show Me the Money, a Pink Panther design on an oversized tee.', 'black', 12),
  ('pink-panther-no-place-like-home', 'pink-panther', 'No Place Like Home', 'No Place Like Home, a Pink Panther design on an oversized tee.', 'black', 13),
  ('pink-panther-phone-home', 'pink-panther', 'Phone Home', 'Phone Home, a Pink Panther design on an oversized tee.', 'black', 14),
  ('pink-panther-houston', 'pink-panther', 'Houston', 'Houston, a Pink Panther design on an oversized tee.', 'black', 15),
  ('pink-panther-im-walking-here', 'pink-panther', 'I''m Walking Here', 'I''m Walking Here, a Pink Panther design on an oversized tee.', 'black', 16)
) as v (id, collection_id, name, description, default_color, ord)
cross join (select coalesce(max(sort_order), 0) as m from public.products) as base;

create temporary table batch_products (id text primary key) on commit drop;
insert into batch_products (id) values ('pink-panther-instant-photographer'), ('pink-panther-no-spill-skater'), ('pink-panther-the-last-drop'), ('pink-panther-low-budget-wind-machine'), ('pink-panther-record-store'), ('pink-panther-bookworm'), ('pink-panther-pizza-tail'), ('pink-panther-sandcastle-architect'), ('pink-panther-mirrorball'), ('pink-panther-poolside'), ('pink-panther-king-of-the-world'), ('pink-panther-show-me-the-money'), ('pink-panther-no-place-like-home'), ('pink-panther-phone-home'), ('pink-panther-houston'), ('pink-panther-im-walking-here');

insert into public.product_colors (product_id, color, label, sort_order)
select p.id, c.color, c.label, c.sort_order
from public.products p
cross join (values ('black', 'Black', 1), ('white', 'White', 2)) as c (color, label, sort_order)
where p.id in (select id from batch_products)
order by p.sort_order, c.sort_order;

insert into public.product_variants (product_id, color, size)
select pc.product_id, pc.color, s.size
from public.product_colors pc
join public.products p on p.id = pc.product_id
cross join (values ('S', 1), ('M', 2), ('L', 3), ('XL', 4), ('XXL', 5)) as s (size, ord)
where pc.product_id in (select id from batch_products)
order by p.sort_order, pc.sort_order, s.ord;

insert into public.product_prices (product_id, region_code, amount_minor)
select id, 'LK', 349900 from public.products where id in (select id from batch_products) order by sort_order;

insert into public.product_prices (product_id, region_code, amount_minor)
select id, 'UK', 1999 from public.products where id in (select id from batch_products) order by sort_order;

insert into public.product_prices (product_id, region_code, amount_minor)
select id, 'US', 2499 from public.products where id in (select id from batch_products) order by sort_order;

-- The linked store gets its mockups from Storage so the collection can appear
-- on the existing deployment. Other databases use the bundled WebP files.
update public.products p
set image_base = 'https://ibepqtmpoqdwqtqcqtzf.supabase.co/storage/v1/object/public/product-images/' || p.id || '/batch-v1'
where p.id in (select id from batch_products)
and not exists (
  select 1
  from batch_products b
  cross join (values ('black'), ('white'), ('black-480'), ('white-480')) as asset(variant)
  where not exists (
    select 1 from storage.objects o
    where o.bucket_id = 'product-images'
    and o.name = b.id || '/batch-v1-' || asset.variant || '.webp'
  )
);
